using GestionMagasin.Domain;
using Microsoft.Data.Sqlite;

namespace GestionMagasin.Infrastructure;

public sealed class SqliteSaleRepository(SqliteConnectionFactory factory) : IVenteRepository
{
    public async Task<Vente?> GetByIdAsync(Guid id, CancellationToken ct=default) { await using var c=factory.Create(); await using var cmd=c.CreateCommand(); cmd.CommandText="SELECT Id,Numero,UtilisateurId,TotalFcfa,DateTechniqueUtc,DateMetier,FuseauHoraire FROM Vente WHERE Id=$id"; cmd.Parameters.AddWithValue("$id",id.ToString()); await using var r=await cmd.ExecuteReaderAsync(ct); return await r.ReadAsync(ct)?new Vente(Guid.Parse(r.GetString(0)),r.GetString(1),Guid.Parse(r.GetString(2)),r.GetInt64(3),DateTime.Parse(r.GetString(4),null,System.Globalization.DateTimeStyles.RoundtripKind),DateTime.Parse(r.GetString(5)),r.GetString(6)):null; }
    public async Task<VenteResultat> ValiderAsync(Utilisateur vendeur,IReadOnlyList<PanierLigne> panier,string modePaiement,long montantRecuFcfa,string fuseauHoraire,CancellationToken ct=default)
    {
        var lignes=panier.GroupBy(x=>x.ProduitId).Select(g=>new PanierLigne(g.Key,g.Sum(x=>x.Quantite),g.First().ReferenceAttendue,g.First().PrixAttenduFcfa)).ToList();
        await using var c=factory.Create(); await using var tx=c.BeginTransaction(); var prix=new List<(PanierLigne Line,string Ref,string Name,long Unit,int Stock)>();
        foreach(var line in lignes){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="SELECT Reference,Nom,PrixVenteFcfa,Actif,COALESCE((SELECT SUM(Quantite) FROM MouvementStock WHERE ProduitId=p.Id),0) FROM Produit p WHERE p.Id=$id";q.Parameters.AddWithValue("$id",line.ProduitId.ToString());await using var r=await q.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))throw new DomainException("Produit introuvable.");if(r.GetInt64(3)!=1)throw new DomainException($"Le produit {r.GetString(1)} est archivé.");var currentPrice=r.GetInt64(2);if(line.PrixAttenduFcfa is not null&&line.PrixAttenduFcfa!=currentPrice)throw new PrixProduitModifieException($"Le prix du produit {r.GetString(1)} a changé. Actualisez le panier.");var available=Convert.ToInt32(r.GetInt64(4));if(line.Quantite>available)throw new StockInsuffisantException($"Stock insuffisant pour {r.GetString(1)} : disponible {available}, demandé {line.Quantite}.");prix.Add((line,r.GetString(0),r.GetString(1),currentPrice,available));}
        var total=prix.Sum(x=>x.Unit*x.Line.Quantite);var received=modePaiement==ModesPaiement.Especes?montantRecuFcfa:total;if(modePaiement==ModesPaiement.Especes&&received<total)throw new DomainException("Le montant reçu est insuffisant.");var change=received-total;var now=DateTime.UtcNow;var zone=ResolveZone(fuseauHoraire);var business=TimeZoneInfo.ConvertTimeFromUtc(now,zone);var id=Guid.NewGuid();var number=$"V-{business:yyyyMMdd-HHmmss}-{Guid.NewGuid().ToString("N")[..6].ToUpperInvariant()}";var token=Guid.NewGuid().ToString("N");
        await Exec(c,tx,"INSERT INTO Vente(Id,Numero,UtilisateurId,TotalFcfa,DateTechniqueUtc,DateMetier,FuseauHoraire,CreeLeUtc,TokenValidation,Statut,ModePaiement,MontantRecuFcfa,MonnaieRendueFcfa) VALUES($id,$n,$u,$total,$utc,$business,$zone,$utc,$token,'VALIDEE',$mode,$received,$change)",("$id",id.ToString()),("$n",number),("$u",vendeur.Id.ToString()),("$total",total),("$utc",now.ToString("O")),("$business",business.ToString("O")),("$zone",zone.Id),("$token",token),("$mode",modePaiement),("$received",received),("$change",change));
        foreach(var item in prix){var lineId=Guid.NewGuid();await Exec(c,tx,"INSERT INTO LigneVente(Id,VenteId,ProduitId,ReferenceSnapshot,NomSnapshot,PrixUnitaireFcfa,Quantite) VALUES($id,$v,$p,$ref,$nom,$price,$q)",("$id",lineId.ToString()),("$v",id.ToString()),("$p",item.Line.ProduitId.ToString()),("$ref",item.Ref),("$nom",item.Name),("$price",item.Unit),("$q",item.Line.Quantite));await Exec(c,tx,"INSERT INTO MouvementStock(Id,ProduitId,Quantite,Type,Motif,ReferenceSource,UtilisateurId,DateTechniqueUtc) VALUES($id,$p,$q,'VENTE',$motif,$source,$u,$d)",("$id",Guid.NewGuid().ToString()),("$p",item.Line.ProduitId.ToString()),("$q",-item.Line.Quantite),("$motif",$"Vente {number}"),("$source",id.ToString()),("$u",vendeur.Id.ToString()),("$d",now.ToString("O")));}
        await tx.CommitAsync(ct);return new VenteResultat(id,number,token,total,received,change);
    }
    public async Task<IReadOnlyList<VenteHistorique>> RechercherAsync(string? numero,DateTime? du,DateTime? au,Guid? vendeurId,string? statut,Utilisateur acteur,CancellationToken ct=default){await using var c=factory.Create();await using var cmd=c.CreateCommand();cmd.CommandText="SELECT v.Id,v.Numero,v.DateMetier,u.NomComplet,v.TotalFcfa,v.ModePaiement,v.Statut FROM Vente v JOIN Utilisateur u ON u.Id=v.UtilisateurId WHERE ($n='' OR v.Numero LIKE $like) AND ($du='' OR v.DateTechniqueUtc >= $du) AND ($au='' OR v.DateTechniqueUtc < $au) AND ($vendeur='' OR v.UtilisateurId=$vendeur) AND ($statut='' OR v.Statut=$statut) AND ($admin=1 OR v.UtilisateurId=$current) ORDER BY v.DateTechniqueUtc DESC";var n=numero?.Trim()??"";cmd.Parameters.AddWithValue("$n",n);cmd.Parameters.AddWithValue("$like",$"%{n}%");cmd.Parameters.AddWithValue("$du",du?.ToUniversalTime().ToString("O")??"");cmd.Parameters.AddWithValue("$au",au?.ToUniversalTime().ToString("O")??"");cmd.Parameters.AddWithValue("$vendeur",vendeurId?.ToString()??"");cmd.Parameters.AddWithValue("$statut",statut??"");cmd.Parameters.AddWithValue("$admin",acteur.Role==Roles.Administrateur?1:0);cmd.Parameters.AddWithValue("$current",acteur.Id.ToString());var list=new List<VenteHistorique>();await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new VenteHistorique(Guid.Parse(r.GetString(0)),r.GetString(1),DateTime.Parse(r.GetString(2)),r.GetString(3),r.GetInt64(4),r.GetString(5),r.GetString(6)));return list;}
    public async Task<VenteDetail?> ObtenirDetailAsync(Guid id,CancellationToken ct=default){await using var c=factory.Create();await using var cmd=c.CreateCommand();cmd.CommandText="SELECT v.Id,v.Numero,v.DateMetier,u.NomComplet,v.TotalFcfa,v.ModePaiement,v.Statut,v.MontantRecuFcfa,v.MonnaieRendueFcfa,l.Id,l.ProduitId,l.ReferenceSnapshot,l.NomSnapshot,l.PrixUnitaireFcfa,l.Quantite FROM Vente v JOIN Utilisateur u ON u.Id=v.UtilisateurId JOIN LigneVente l ON l.VenteId=v.Id WHERE v.Id=$id";cmd.Parameters.AddWithValue("$id",id.ToString());await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;var history=new VenteHistorique(Guid.Parse(r.GetString(0)),r.GetString(1),DateTime.Parse(r.GetString(2)),r.GetString(3),r.GetInt64(4),r.GetString(5),r.GetString(6));var received=r.GetInt64(7);var change=r.GetInt64(8);var lines=new List<LigneVente>();do{lines.Add(new LigneVente(Guid.Parse(r.GetString(9)),id,Guid.Parse(r.GetString(10)),r.GetString(11),r.GetString(12),r.GetInt64(13),r.GetInt32(14)));}while(await r.ReadAsync(ct));return new VenteDetail(history,lines,received,change);}
    public async Task AnnulerAsync(Guid id,Utilisateur admin,string motif,CancellationToken ct=default){await using var c=factory.Create();await using var tx=c.BeginTransaction();await using var sale=c.CreateCommand();sale.Transaction=tx;sale.CommandText="SELECT Numero,Statut FROM Vente WHERE Id=$id";sale.Parameters.AddWithValue("$id",id.ToString());await using var sr=await sale.ExecuteReaderAsync(ct);if(!await sr.ReadAsync(ct))throw new DomainException("Vente introuvable.");var number=sr.GetString(0);if(sr.GetString(1)=="ANNULEE")throw new DomainException("Cette vente est déjà annulée.");await sr.DisposeAsync();var now=DateTime.UtcNow;await Exec(c,tx,"INSERT INTO AnnulationVente(Id,VenteId,UtilisateurId,Motif,DateTechniqueUtc) VALUES($id,$v,$u,$m,$d)",("$id",Guid.NewGuid().ToString()),("$v",id.ToString()),("$u",admin.Id.ToString()),("$m",motif),("$d",now.ToString("O")));await Exec(c,tx,"UPDATE Vente SET Statut='ANNULEE' WHERE Id=$id",("$id",id.ToString()));await using var lines=c.CreateCommand();lines.Transaction=tx;lines.CommandText="SELECT ProduitId,Quantite FROM LigneVente WHERE VenteId=$id";lines.Parameters.AddWithValue("$id",id.ToString());await using var lr=await lines.ExecuteReaderAsync(ct);var items=new List<(string,int)>();while(await lr.ReadAsync(ct))items.Add((lr.GetString(0),lr.GetInt32(1)));await lr.DisposeAsync();foreach(var item in items)await Exec(c,tx,"INSERT INTO MouvementStock(Id,ProduitId,Quantite,Type,Motif,ReferenceSource,UtilisateurId,DateTechniqueUtc) VALUES($id,$p,$q,'ANNULATION',$m,$source,$u,$d)",("$id",Guid.NewGuid().ToString()),("$p",item.Item1),("$q",item.Item2),("$m",$"Annulation vente {number}: {motif}"),("$source",id.ToString()),("$u",admin.Id.ToString()),("$d",now.ToString("O")));await tx.CommitAsync(ct);}
    static TimeZoneInfo ResolveZone(string id){try{return TimeZoneInfo.FindSystemTimeZoneById(string.IsNullOrWhiteSpace(id)?TimeZoneInfo.Local.Id:id);}catch{return TimeZoneInfo.Local;}}
    static async Task Exec(SqliteConnection c,SqliteTransaction tx,string sql,params (string Name,object Value)[] values){await Exec(c,tx,sql,values,default);}
    static async Task Exec(SqliteConnection c,SqliteTransaction tx,string sql,(string Name,object Value)[] values,CancellationToken ct){await using var cmd=c.CreateCommand();cmd.Transaction=tx;cmd.CommandText=sql;foreach(var v in values)cmd.Parameters.AddWithValue(v.Name,v.Value);await cmd.ExecuteNonQueryAsync(ct);}
}
